}

arguments.new:
        // vertical entry groove, open at the rim
        rotate([0, 0, a - 8])
            rotate_extrude(angle = 16)
                polygon(points = [[slot_bot_r, slot_z_bot], [38, slot_z_bot],
                                  [38, jar_h + 2], [slot_bot_r, jar_h + 2]]);
        // detent pocket: groove floor dips at the locked end; the lid rides raised
        // on its lugs during the turn and drops into the pocket to lock
        rotate([0, 0, a + 82])
            rotate_extrude(angle = 16)
                polygon(points = [[slot_bot_r - 0.1, slot_z_bot - pocket_depth], [34.3, slot_z_bot - pocket_depth],
                                  [34.3, slot_z_bot + 0.05], [slot_bot_r - 0.1, slot_z_bot + 0.05]]);
    }
}
